1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"io"
7		"strings"
8	
9		"github.com/entireio/cli/cmd/entire/cli/api"
10		"github.com/entireio/cli/cmd/entire/cli/auth"
11		"github.com/entireio/cli/cmd/entire/cli/gitremote"
12		"github.com/entireio/cli/cmd/entire/cli/logging"
13		"github.com/entireio/cli/internal/coreapi"
14	)
15	
16	// runAuthenticatedActivityAPI runs fn with an authenticated client for the
17	// activity/recap surface. It prefers the caller's home entire-api cell (the same
18	// shared client the experts commands use), which serves the /me/* endpoints
19	// these commands call.
20	//
21	// Cell routing is a best-effort upgrade: any failure building the cell client —
22	// the region has no cell yet (ErrNoCellForJurisdiction), not logged in, or a
23	// discovery/exchange error — falls back to the data API, which also serves
24	// /me/* and yields the canonical auth errors (e.g. the "not logged in" hint).
25	// This keeps the migration transparent and non-regressive; non-obvious
26	// fallbacks are logged for diagnosis. Both backends expose the same /me/* paths,
27	// so fn is agnostic to which client it receives.
28	func runAuthenticatedActivityAPI(ctx context.Context, errW io.Writer, insecureHTTP bool, fn func(context.Context, *api.Client) error) error {
29		client, err := auth.NewEntireAPICellClient(ctx, insecureHTTP, nil)
30		if err != nil {
31			logCellClientFallback(ctx, err)
32			return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, fn)
33		}
34		return fn(ctx, client)
35	}
36	
37	// logCellClientFallback records, at debug, that an activity/recap command fell
38	// back from the entire-api cell to the data API. The expected cases — the
39	// region has no cell yet, or the caller isn't logged in — aren't logged: they
40	// are normal during rollout and on first use, not diagnosable failures.
41	func logCellClientFallback(ctx context.Context, err error) {
42		if errors.Is(err, auth.ErrNoCellForJurisdiction) || errors.Is(err, auth.ErrNotLoggedIn) {
43			return
44		}
45		logging.Debug(ctx, "activity/recap: entire-api cell client unavailable, using data API", "error", err.Error())
46	}
47	
48	// forgeToMirrorProvider maps a gitremote forge identifier (e.g. "gh") to the
49	// upstream provider the control plane records mirrors under (e.g. "github").
50	// entire-api routing only supports GitHub mirrors today.
51	func forgeToMirrorProvider(forge string) (string, bool) {
52		switch strings.ToLower(strings.TrimSpace(forge)) {
53		case "gh", mirrorCloneProviderGitHub:
54			return mirrorCloneProviderGitHub, true
55		default:
56			return "", false
57		}
58	}
59	
60	// currentRepoID best-effort resolves the current repo (its "origin" remote) to
61	// the ULID entire-api uses for repo-scoped params — recap's /me/recap?repo=.
62	// entire.io/api documents the mirror id as exactly that repo_id (repo_id =
63	// mirror_repos.id), and the CLI already lists mirrors via the control plane, so
64	// no extra resolution is needed. Any failure returns "" — recap then shows the
65	// personal side only rather than erroring.
66	func currentRepoID(ctx context.Context) string {
67		forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
68		if err != nil {
69			return ""
70		}
71		provider, ok := forgeToMirrorProvider(forge)
72		if !ok {
73			return ""
74		}
75		c, err := coreapi.New()
76		if err != nil {
77			return ""
78		}
79		mirrors, err := listMirrorsForRepo(ctx, c, provider, strings.ToLower(owner), repo)
80		if err != nil {
81			return ""
82		}
83		return firstActiveRepoID(mirrors)
84	}
85	
86	// firstActiveRepoID returns the id of the repo's first active mirror (the repo
87	// id is stable across a repo's placements, so any active one serves). Archived
88	// and failed/suspended placements are skipped — they can't answer for the repo.
